import {ageLabel,dateLabel,primaryRetirementAge,ruleOf55Applies} from './model.js';

const money=value=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(value||0);
const percent=value=>`${Number((value*100).toFixed(2))}%`;
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const edit=(label,index=4)=>`<button class="text-link" data-action="withdrawal-settings" data-index="${index}">${label} →</button>`;
const row=(label,value)=>`<div><dt>${escape(label)}</dt><dd>${money(value)}</dd></div>`;
const section=(title,content)=>`<section class="card"><h2>${title}</h2>${content}</section>`;

function exampleDetails(p){
  const f=p.cashFlow;
  const sources=(f.workingSupport!==undefined?row('Take-home household support',f.workingSupport):'')+row('Social Security',f.socialSecurity)+row('Guaranteed income',f.guaranteedIncome)+row('Scheduled SEPP payment',f.seppDistribution)+row('Required minimum distribution',f.rmdDistribution)+row('Additional withdrawal needed',f.additionalWithdrawal);
  const uses=row('Modeled expenses',f.expenses)+row(f.incomeTax<0?'Federal income tax adjustment':'Federal income tax',f.incomeTax)+row('Early-withdrawal penalties',f.earlyPenalty)+row('Surplus available for cash',f.surplus);
  return `<p>Month ${p.month}${p.date?` · ${dateLabel(p.date)}`:''} · Closing age ${ageLabel(p.age)}. ${f.seppProtected?'The SEPP restriction is active; extra spending uses other accounts.':f.cashFirst?'The drawdown trigger is met, so available cash is used first.':'The default spending withdrawal order applies.'}</p><div class="withdrawal-example-grid"><div><h3>Money available for this month</h3><dl class="withdrawal-ledger">${sources}</dl></div><div><h3>What it needs to cover</h3><dl class="withdrawal-ledger">${uses}</dl></div></div><p class="form-note">Expenses include modeled living costs, housing payments, healthcare, and any home-sale mortgage shortfall. Scheduled distributions are counted once, before calculating the additional withdrawal. Federal tax is the change in modeled year-to-date liability; a negative adjustment returns money to the plan.</p>${p.unfundedAmount>0?`<p class="notice warning">This month ends with an unfunded amount of ${money(p.unfundedAmount)}. The amount needed above could not all be supplied by the plan.</p>`:''}<details class="inset-details"><summary>Account withdrawals and closing balances</summary><p class="form-note">These withdrawals include scheduled distributions and additional spending withdrawals. Conversions and their tax payments are shown separately below. ${f.savingsContributions!==undefined?`Additional savings deposits this month: ${money(f.savingsContributions)}. They are not income available twice. `:''}Returns also change balances; the difference between opening and closing balances is not just spending.</p><div class="withdrawal-example-grid"><div><h3>Drawn from accounts</h3><dl class="withdrawal-ledger">${Object.entries({pretax:'Pre-tax',roth:'Roth',taxable:'Taxable',cash:'Cash'}).map(([key,label])=>row(label,f.accountWithdrawals[key])).join('')}</dl></div><div><h3>Closing balances</h3><dl class="withdrawal-ledger">${Object.entries({pretax:'Pre-tax',roth:'Roth',taxable:'Taxable',cash:'Cash',home:'Home value',mortgage:'Mortgage debt',portfolio:'Portfolio total',netAssets:'Net assets'}).map(([key,label])=>row(label,p[key])).join('')}</dl></div></div></details><p>${f.conversionAmount>0?`After this month’s spending, ${money(f.conversionAmount)} moves from pre-tax savings to Roth, with ${money(f.conversionTax)} in additional modeled conversion tax. This transfer is not spending income.`:'No Roth conversion takes place in this month.'} <button class="text-link" data-view="results">View monthly balances →</button></p>`;
}

export function withdrawalContent(s,r,month=1,exampleOnly=false){
  const w=s.withdrawalStrategy,c=s.rothConversion,seppStarts=w.seppEligible&&primaryRetirementAge(s)<59.5;
  const months=r?.steadySimulation?.monthlyDetails.filter(p=>p.cashFlow)??[];
  const selected=months.find(p=>p.month===month)??months[0];
  if(exampleOnly)return selected?exampleDetails(selected):'<p>Run this plan to see a monthly example.</p>';
  const settings=`<p>For <strong>${escape(s.name)}</strong>. These are the selected plan’s current assumptions.</p><dl class="withdrawal-settings"><div><dt>Spending withdrawal order</dt><dd>${seppStarts?(s.household.separatePeople?'Owner-specific scheduled SEPP first; other eligible pre-tax balances remain available.':'Scheduled SEPP first; extra spending uses Roth → taxable → cash.'):'Pre-tax → Roth → taxable → cash.'}</dd></div><div><dt>Cash in market drawdowns</dt><dd>${w.useCashReserveDuringDrawdowns?`On · Available cash comes first when the modeled monthly portfolio return is below ${percent(w.drawdownTrigger)}. Current cash: ${money(s.accounts.cash)}.`:'Off · Cash is used after the invested accounts.'}</dd></div><div><dt>Early-withdrawal penalties</dt><dd>${w.applyEarlyWithdrawalPenalty?'On · Applicable modeled penalties before age 59½ are funded along with expenses.':'Off · Early-withdrawal penalties are omitted; federal income taxes still apply.'}</dd></div><div><dt>${s.household.separatePeople?'Your ':''}Rule of 55 declaration</dt><dd>${w.ruleOf55Eligible?(ruleOf55Applies(s)?'Selected · The retirement timing passes the model’s age test. This relies on your employer-plan eligibility declaration.':'Selected, but the retirement timing does not pass the model’s age test. The declaration has no effect with these dates.'):'Not selected.'} It does not exempt IRA or Roth distributions.</dd></div><div><dt>${s.household.separatePeople?'Your ':''}72(t) / SEPP plan</dt><dd>${w.seppEligible?(seppStarts?'Selected · A scheduled pre-tax payment starts at retirement. Extra pre-tax withdrawals and conversions are blocked during the modeled restriction.':'Selected, but retirement starts at age 59½ or later, so this model does not start SEPP payments.'):'Not selected.'}</dd></div><div><dt>Roth conversions</dt><dd>${c.enabled?`On · At the end of each complete modeled year, the engine tests a conversion up to the selected ${percent(c.marginalRateCap)} federal bracket cap. A conversion can be zero when there is no room or SEPP protection applies.`:'Off · No additional pre-tax-to-Roth transfers are modeled.'}</dd></div>${s.household.separatePeople&&s.household.filingStatus==='Married'?`<div><dt>Spouse early-access declarations</dt><dd>Rule of 55: ${s.spouseWithdrawal.ruleOf55Eligible?'selected':'not selected'}. SEPP: ${s.spouseWithdrawal.seppEligible?'selected':'not selected'}. Their own retirement date and age determine timing; a protected spouse balance is excluded from extra withdrawals and conversions.</dd></div>`:''}</dl>${edit('Edit withdrawal settings')} <span class="muted">·</span> ${edit('Edit account and Roth history',1)}`;
  const steps=`<ol class="withdrawal-steps"><li><strong>Work out this month’s costs.</strong><p>Apply the plan’s spending pattern and inflation, then include housing and healthcare costs. Household deaths, long-term care, and the selected spending cut can change those costs.</p></li><li><strong>Count income and scheduled distributions.</strong><p>Social Security and guaranteed income follow their start dates and survivor rules. Scheduled SEPP and required minimum distributions come from pre-tax savings and help fund the same month.</p></li><li><strong>Withdraw enough to cover the remaining need.</strong><p>After investment returns and cash interest, the engine uses the account order below and calculates the extra withdrawal needed to pay costs, federal income taxes, and any modeled penalties. Taking more pre-tax money can increase tax, so it solves for the amount that covers both.</p></li><li><strong>Record the remaining balances.</strong><p>Unused after-tax income or distributions remain in cash. Optional year-end Roth conversions move money between accounts and require a separate tax payment. Mortgage payments reduce debt. If available funds cannot cover costs, the model can sell the home; an unresolved gap ends that path.</p></li></ol>${edit('Review spending assumptions',1)} <span class="muted">·</span> ${edit('Review income assumptions',2)}`;
  const order=`<p class="withdrawal-order">Pre-tax <span aria-hidden="true">→</span> Roth <span aria-hidden="true">→</span> Taxable <span aria-hidden="true">→</span> Cash</p><p>This is the simulator’s fixed default for ordinary spending. It does not search for the most tax-efficient withdrawal strategy.</p><ul class="withdrawal-notes"><li><strong>Cash-first option:</strong> available cash moves to the front when that month’s portfolio return falls below your trigger. This compares a monthly return, not the cumulative fall from a market peak.</li><li><strong>Required minimum distributions (RMDs):</strong> ordinary pre-tax spending draws count toward the annual minimum. The model spreads the remaining requirement through the modeled year; unused after-tax proceeds stay in cash. RMDs are handled before conversions.</li><li><strong>SEPP:</strong> a series started before 59½ restricts extra access to ${s.household.separatePeople?'that owner’s pre-tax balance':'the entire pre-tax pool'} until the later of five years or age 59½. Other accounts fund an extra spending gap. Protected pre-tax savings can remain even when a path runs short.</li><li><strong>Conversion taxes:</strong> paid separately in cash → taxable → Roth → pre-tax order. A conversion transfers savings to Roth; it is not money available for this month’s living costs.</li></ul>`;
  const example=selected?`<p>Actual cash flows from the separate steady-growth simulation: zero volatility, no long-term care risk, and the longer assumed lifespans described on Results. This is an illustration, not the statistical median.</p><div class="field withdrawal-month-picker"><label for="withdrawal-example-month">Example month</label><select id="withdrawal-example-month">${months.map(p=>`<option value="${p.month}" ${p.month===selected.month?'selected':''}>Month ${p.month}${p.date?` · ${dateLabel(p.date)}`:''}</option>`).join('')}</select></div><div id="withdrawal-example" aria-live="polite">${exampleDetails(selected)}</div>`:r?.steadySimulation?.endReason==='before-retirement'?'<p>The assumed household lifespan ends on or before retirement begins, so this plan has no retirement month to illustrate. Review your household dates.</p>'+edit('Review household dates',0):'<p>Run the selected plan to see an actual month from its steady-growth simulation. The explanation above is available before a run.</p><button class="primary" data-action="run-plan">Run this plan →</button>';
  const details=`<details class="card"><summary>Taxes, Roth rules, and model limits</summary><div class="withdrawal-notes"><h3>What is treated as taxable</h3><p>Pre-tax distributions, guaranteed income, cash interest, conversions, and nonqualified Roth earnings enter the simplified federal tax calculation. Part of Social Security can also become taxable. The model charges changes in year-to-date liability; it does not schedule tax withholding or estimated payments.</p><h3>How Roth withdrawals are ordered</h3><p>Regular contributions come first, then conversions oldest first, then earnings. Within a conversion year, taxable principal comes before nontaxable principal. The entered history and modeled five-tax-year clocks determine qualification and applicable penalties. A Roth withdrawal is not automatically tax-free.</p><h3>What to keep in mind</h3><p>State and local income taxes, taxable-account capital gains and dividend taxes, and taxes on taxable-account withdrawals are not modeled. Tax years follow retirement anniversaries rather than calendar years. ${s.household.separatePeople?'Pre-tax and Roth balances and Roth histories have separate owners; each follows their own age, RMD, penalty and selected SEPP rules. Spending uses your available pre-tax balance, then spouse pre-tax, then your Roth, spouse Roth, shared taxable and cash. Spouse inherited accounts become their own after the modeled death year. Take-home support does not model employment gross income, taxes or Medicare effects.':'Account balances are pooled as primary-owned, then surviving-spouse-owned after the primary death year; separate spouse histories are not modeled.'} RMD timing is simplified and does not model first-year deferral.</p><p>These rules explain this calculator’s assumptions, rather than recommend a withdrawal strategy. <a href="./methodology.html">Read the full model scope and limitations →</a></p></div></details>`;
  return `<div class="stack withdrawals-page">${section('Your withdrawal assumptions',settings)}${section('How a month works',steps)}${section('Which savings are used first?',order)}${section('A month from your plan',example)}${details}</div>`;
}
